fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Zip the two input vectors, compare each pair element-wise,
    // and collect the boolean results into a new Vec<bool>.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x < y)
     .collect()
}

